{
  "decline_reason": "",
  "claims": [
    {
      "text": "Under the Manual’s practice, if the Registrar does not notify the person of an underpayment within 14 working days of making an application, notice or request, it is treated as filed despite the unpaid fee.",
      "quotes": [
        {
          "ref": "TMM/Part2/4/part-2-4-3-fee-not-paid-or-underpaid",
          "quote": "Where the Registrar fails to notify the person of an underpayment within 14 working days of the person making an application, notice or request, then the application, notice or request is treated as filed despite the failure to pay the relevant fee (reg 21.21A(2))."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual states that, where notification is not given within the allowed period, the document is taken to be filed on the date it is received.",
      "quotes": [
        {
          "ref": "TMM/Part4/6/6/3/3",
          "quote": "If the Registrar does not notify the person within the 14 days allowed by subsection 223(5) (reg 21.23), the document is taken to be filed on the date it is received."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The missed notification deadline does not waive the fee: the Manual states that the unpaid amount remains a debt owed to the Commonwealth.",
      "quotes": [
        {
          "ref": "TMM/Part2/4/part-2-4-3-fee-not-paid-or-underpaid",
          "quote": "However, reg 21.21A(2) does not have the effect of waiving the fee. The fee or amount unpaid remains a debt owed to the Commonwealth."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Deemed filing does not permit the Registrar to perform an act for which a fee is payable until that fee has been paid.",
      "quotes": [
        {
          "ref": "TMR1995/r21.21A(1)",
          "quote": "(1) If a fee is payable in respect of the doing of an act by the Registrar or the Comptroller-General of Customs, the Registrar or Comptroller-General of Customs must not do the act until the fee has been paid."
        }
      ],
      "authority": "legislation"
    },
    {
      "text": "The Manual also requires written notification of the fee deficiency as soon as practicable even where the initial notification deadline was missed.",
      "quotes": [
        {
          "ref": "TMM/Part4/1/1/3/1",
          "quote": "If the Registrar does not notify an applicant within 14 days of the underpayment or non-payment of the fee,the request is taken to be made, but the applicant must still be notified in writing of the deficiency in the fee as soon as practicable."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The supplied Manual passages use both ‘14 working days’ and ‘14 days’; regulation 21.23 is not supplied, so the precise statutory calculation of that period cannot be verified from these passages.",
      "quotes": [],
      "authority": "none"
    }
  ],
  "declined": false,
  "concepts_used": [
    "GC-0046",
    "GC-0091"
  ]
}
